import{_ as t,o as n,c as a,a2 as r}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"Contract Fidelity and Evolution","description":"What emitted payload validation and independent producer/consumer fixtures establish, and what they do not.","frontmatter":{"title":"Contract Fidelity and Evolution","description":"What emitted payload validation and independent producer/consumer fixtures establish, and what they do not."},"headers":[],"relativePath":"guide/schema-conversion/contract-fidelity.md","filePath":"guide/schema-conversion/contract-fidelity.md","lastUpdated":1789026761000}'),o={name:"guide/schema-conversion/contract-fidelity.md"};function d(i,e,s,c,l,u){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="contract-fidelity-and-evolution" tabindex="-1">Contract fidelity and evolution <a class="header-anchor" href="#contract-fidelity-and-evolution" aria-label="Permalink to &quot;Contract fidelity and evolution&quot;">​</a></h1><p>An AsyncAPI document can parse successfully while admitting an invalid message. The contract suites keep four independent layers of evidence: TypeSpec diagnostics, document/schema parsing, supplied payload <strong>and application-header</strong> acceptance, and old-writer/new-reader serialization. A snapshot or successful binary decode alone does not establish source-contract preservation.</p><h2 id="validated-dialects" tabindex="-1">Validated dialects <a class="header-anchor" href="#validated-dialects" aria-label="Permalink to &quot;Validated dialects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lane</th><th>Generated contracts</th><th>Authored contracts</th><th>Instance evidence</th></tr></thead><tbody><tr><td>Native AsyncAPI 3.1 / JSON Schema draft-07</td><td>Supported subset below</td><td>AsyncAPI and draft-07 JSON/YAML identifiers</td><td>Isolated Ajv + ajv-formats, retained recursive references</td></tr><tr><td>Avro 1.9.0</td><td>Preview Avro record conversion</td><td>Avro object schemas</td><td>avsc writer encoding and independent reader resolution</td></tr><tr><td>Protobuf 3</td><td>Preview self-contained proto3</td><td>Authored proto3 text</td><td>protobufjs independently parsed writer/reader, explicit root</td></tr><tr><td>Protobuf 2</td><td>No generated lane</td><td>Focused authored proto2</td><td>Required fields and defaults, not a generated proto2 promise</td></tr><tr><td>OpenAPI 3.0, RAML 1.0, other identifiers</td><td>No conversion claim</td><td>Identifier/representation pass-through</td><td>Not validated as draft-07; the instance helper refuses these lanes</td></tr></tbody></table><p>Accepting fourteen <code>schemaFormat</code> identifiers is not evidence of fourteen payload-validation implementations. The wrapper&#39;s media type and schema syntax are separate assertions. Both JSON and YAML document serialization are exercised for native, generated Avro and generated proto3 payloads.</p><h2 id="supported-feature-matrix" tabindex="-1">Supported-feature matrix <a class="header-anchor" href="#supported-feature-matrix" aria-label="Permalink to &quot;Supported-feature matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>IDs</th><th>Native JSON witnesses</th><th>Binary evidence or explicit limitation</th></tr></thead><tbody><tr><td>F01</td><td>Length endpoints, patterns, UUID and date-time, format profiles</td><td>Unsupported source constraints/formats refuse generated artifacts</td></tr><tr><td>F02</td><td>Inclusive/exclusive bounds, fractions, signed widths, safe-number boundaries</td><td>Exact supported integer/byte representations; wider values use codec-specific representations</td></tr><tr><td>F03</td><td>Item bounds, item types, named arrays, records</td><td>Supported arrays/maps; constrained or indexed-record shapes are refused where unsupported</td></tr><tr><td>F04</td><td>Required/optional, nullable/nonnullable, defaults without injection</td><td>Avro null/default resolution; proto3 wire presence is not TypeSpec requiredness; explicit source defaults refused</td></tr><tr><td>F05</td><td>Epoch, duration, bytes alphabets, encoded string representation, nullable branches, defaults/examples, scalar-chain constraints</td><td>Source <code>@encode</code> is refused rather than silently ignored by binary conversion</td></tr><tr><td>F06</td><td>Literals/enums, overlapping anyOf/oneOf, empty sets, discriminated envelopes</td><td>Avro branch restrictions, enum/default behavior; protobuf numeric enums, unsupported unions</td></tr><tr><td>F07</td><td>Layered scalar/model inheritance, inherited required fields, recursive references and shared components</td><td>Recursive binary records/messages; unsupported inheritance refused; explicit protobuf root and descriptor parity</td></tr><tr><td>F08</td><td>Own, spread and lifting-message inherited headers; explicit separate headers, encoded names and independent failures</td><td>Separate native headers retained beside binary payloads; generated payload lifting refused</td></tr><tr><td>F09</td><td>Actual dialect compilation, malformed schemas, escaped/missing/circular refs, per-document registries</td><td>Authored/generated controls; unsupported dialects do not count as validated</td></tr><tr><td>F10</td><td>Opaque scalar, visibility, numeric/temporal limitations, schema-extension and encoding diagnostics</td><td>Actionable metadata/refusal diagnostics with source targets/counts; Avro logical metadata checked separately</td></tr></tbody></table><p>An inherited <code>@header</code> from an <strong>unmarked</strong> base is not lifted: the existing <code>inherited-header-ignored</code> warning keeps that field in the payload. A base that is itself a lifting <code>@message</code> propagates its headers; spreading also makes a field the message&#39;s own. No change to these rules is implied by the matrix.</p><p>New native warnings make previously silent limitations visible: <code>unmapped-schema-scalar</code>, <code>unsupported-encoded-constraint</code>, <code>unsupported-schema-keyword</code>, and <code>schema-extension-overrides-contract</code>. Malformed known extension keywords report <code>invalid-schema-extension</code> errors. Encoding rewrites every scalar <code>allOf</code> level; constraints for the old wire type are omitted with a warning, not left as meaningless bounds or contradictory types. Nullable unions are inspected by branch domain, including known scalar references and their inherited encodings without changing shared components. Constraints that still apply to another branch remain in place; genuinely unknown reference domains stay conservative. An authored <code>$ref</code> also warns when it displaces generated validation siblings. Enum equality ignores object-key order, and later-draft keywords are detected inside schema-valued <code>dependencies</code>. No numeric-to-string range regex or universal conversion solver is invented.</p><h2 id="consumer-profiles-and-evolution" tabindex="-1">Consumer profiles and evolution <a class="header-anchor" href="#consumer-profiles-and-evolution" aria-label="Permalink to &quot;Consumer profiles and evolution&quot;">​</a></h2><p>The primary JSON profile is <strong>open, format-asserting</strong>: unknown object properties remain allowed, known formats are asserted, enums reject unknown values, and <code>coerceTypes</code>, <code>useDefaults</code>, and <code>removeAdditional</code> are all false. Neither defaults nor failed validation mutate input. A <strong>closed</strong> profile separately lists consumer-known fields at explicit object paths. It does not attach <code>additionalProperties: false</code> to an <code>allOf</code> and mistake inherited fields for unknown ones. A <strong>format-annotation</strong> profile intentionally ignores formats.</p><p>The native/draft-07 oracle ignores validation siblings of <code>$ref</code>; meaningful additional constraints belong in an <code>allOf</code> wrapper. It explicitly rejects OpenAPI <code>nullable</code> at schema positions rather than extending the dialect. Opaque annotations are removed only from the nonmutating compilation view, so their <code>$id</code> values cannot register schemas or resolve live references. Real schema identifiers, recursive references and literal <code>const</code>/<code>enum</code> data remain. Absent optional headers default to an empty object for validation; explicit <code>null</code> does not and fails an object header schema.</p><p>Unknown validation keywords and formats fail helper compilation unless explicitly declared annotation-only. <code>http-date</code> is one such declared lexical limitation. Numeric/boolean string encodings establish the string representation, not a canonical lexical grammar. Integer width formats are assertions in this profile, not a promise that every JSON consumer enforces them. JSON numeric witnesses stay within JavaScript safe precision; decimal128 and full int64/uint64 precision are not proved by JavaScript-number validation.</p><p>Every independent-release mutation runs P1→C1, P1→C2, P2→C1 and P2→C2. The writer must accept its witness before serialization. Fixtures E01–E10 cover optional/required additions, defaults, optionality, removals, wire-name changes, aliases, enums, tightening/loosening constraints, changed types/encodings/tags, and payload/header/envelope changes. Results distinguish rejection from retained values and successful reading with loss or defaulting.</p><p><strong>Even an optional addition is not universally safe.</strong> An old open contract with only <code>id: string</code> accepts <code>{ id: &quot;a&quot;, note: 42 }</code>. Adding <code>note?: string</code> rejects that old-valid message. Conversely, a new string <code>note</code> is accepted by an old open consumer but rejected by a closed consumer. JSON required-field defaults do not rescue old messages: no default is injected.</p><p>Avro uses stable full names and <code>reader.createResolver(writer)</code>, with <code>wrapUnions: false</code>. Unknown writer fields are skipped; aliases are directional; reader defaults and enum fallback are asserted as exact values, not called value-preserving. Unsupported reader/writer pairs can fail during resolver construction or when a particular union/enum branch is read. Generated defaults are checked recursively against the completed Avro schema graph, including named records, arrays, maps and each nested union&#39;s first branch. An outer default never reorders a shared nested union. Invalid or infinitely expanding defaults report <code>tsp-avro/invalid-default</code> and refuse output.</p><p>Protobuf uses separate roots with <code>keepCase: true</code>; the root message is selected explicitly. Values, own-field presence, unknown numeric enums and tag loss are asserted independently. Missing singular fields may decode successfully despite violating source-required semantics. An old reader can discard unknown tags on decode/re-encode. A separate closed-enum application policy rejects unknown numbers. Binary name/tag compatibility does not establish ProtoJSON compatibility. Explicit source metadata is checked throughout a Protobuf scalar&#39;s ancestry, even beyond the nearest supported wire mapping; implicit wire mappings remain supported.</p><p>Avro logical-type names, units, decimal precision/scale and fixed sizes are asserted on the emitted schema. avsc without custom logical adapters does not prove those semantics. <code>local-timestamp-*</code> is refused because it is not part of the advertised Avro 1.9.0 dialect.</p><h2 id="version-generated-retained-messages" tabindex="-1">Version-generated retained messages <a class="header-anchor" href="#version-generated-retained-messages" aria-label="Permalink to &quot;Version-generated retained messages&quot;">​</a></h2><p>The retention suites use real TypeSpec <code>@versioned</code> v1/v2/v3 views through the <a href="./../versioning">versioning adapter</a>, not edited copies of JSON schemas. Before any acceptance assertion, they check the exact output set <code>asyncapi.1.0.json</code>, <code>asyncapi.2.0.json</code>, <code>asyncapi.3.0.json</code>, each selected <code>info.version</code>, the AsyncAPI <strong>3.1.0</strong> target, and live payload/header fields, required sets, enum members, types and constraint bounds.</p><p>Each JSON witness is admitted by its <strong>producer snapshot</strong> and serialized once with <code>readJson</code>. The resulting value and serialized text are retained and reused unchanged by every consumer. No consumer-shaped reconstruction, renaming, coercion, default injection or removal of unknown fields occurs. The ten individually attributable fixtures contain 34 produced records and 204 consumer outcomes (three versions, two policies), including 70 expected rejections.</p><table tabindex="0"><thead><tr><th>Case</th><th>Version-generated change</th><th>Retention evidence</th></tr></thead><tbody><tr><td>R01</td><td>Optional field added in v2</td><td>A declared-only v1 message survives; an old-valid <code>note: 42</code> collides with the new optional string.</td></tr><tr><td>R02</td><td>Required field with a default added in v2</td><td>The v1 omission fails in v2 and v3; a JSON default does not repair it.</td></tr><tr><td>R03a / R03b</td><td>Optional-to-required / required-to-optional</td><td>Separate fixtures expose each direction without one change masking another.</td></tr><tr><td>R04</td><td>Required field removed in v2</td><td>Tolerant readers accept the old extra field without rewriting it; old readers reject new messages missing it.</td></tr><tr><td>R05</td><td>A property renamed in both v2 and v3</td><td>Old, intermediate and current names stay distinct; queued values are not migrated.</td></tr><tr><td>R06</td><td>Enum member added in v2, another removed in v3</td><td>A v1 legacy value survives v2 but fails v3; a new member fails the old consumer.</td></tr><tr><td>R07</td><td>Integer bounds tightened in v2, widened in v3</td><td>Retained endpoints fail the intermediate deployment; newly widened values fail older consumers.</td></tr><tr><td>R08</td><td>String changes to integer, then integer-or-null</td><td>Numeric text is not coerced, and null is admitted only by its actual snapshot.</td></tr><tr><td>R09</td><td>Optional application header added in v2, required in v3</td><td>Header omissions and unknown-name collisions fail independently of the unchanged payload.</td></tr></tbody></table><p><strong>Tolerant</strong> means open to unknown payload/header fields, not tolerant of wrong types, missing required fields, unknown enums, invalid formats or violated bounds. <strong>Strict</strong> applies the same schema checks plus explicit consumer-known field sets for payload and headers; a version with no declared headers knows no header names. All fixture producers use the open profile. Consequently, an open producer&#39;s extra-field witness can fail even a same-version strict consumer.</p><p>A separate deployment control selects <code>&quot;1.0&quot;</code>, then <code>&quot;2.0&quot;</code> and <code>&quot;3.0&quot;</code> in independent emissions. The exact same queued v1 <code>amount: 0</code> is rejected by v2&#39;s minimum of 10 and accepted by v3&#39;s minimum of 0. This assumes the original record is still available; it does not claim that a broker retained it after an earlier consumer attempted delivery.</p><p>Bounded version-generated <strong>Avro 1.9</strong> and <strong>proto3</strong> controls also capture writer bytes once and read the same bytes with independently constructed v1/v2/v3 codecs. Avro asserts exact reader defaults (<code>note: null</code>, <code>generation: 0</code>), dropped fields and two resolver refusals when the required v3 field lacks a default. A v1 relay loses v3 content; later defaults do not restore its original values. Protobuf asserts unknown-tag loss and absent own-field presence. Decoding v1 bytes under v3 succeeds, but the native v3 view of the <strong>same TypeSpec source</strong> rejects the missing source-required <code>generation</code> field. These are semantic-content assertions separate from the unchanged retained bytes, not a promise of byte-preserving decode/re-encode.</p><p>The broader <a href="https://github.com/cataggar/tsp-asyncapi/blob/main/test/integration/contract-binary-evolution.test.ts" target="_blank" rel="noreferrer">independent binary writer/reader matrix</a> continues to cover aliases, enums, type/tag changes and reader/writer restrictions; the retention controls do not duplicate or expand that capability claim. The harness retains the producer schema and codec identity alongside each record (Avro resolution requires the writer schema). It models no schema-registry availability, application migration, broker storage or delivery operation.</p><h2 id="scope-and-running-the-evidence" tabindex="-1">Scope and running the evidence <a class="header-anchor" href="#scope-and-running-the-evidence" aria-label="Permalink to &quot;Scope and running the evidence&quot;">​</a></h2><p>The existing Vitest runner auto-discovers <code>contract-fidelity</code>, <code>contract-native-diagnostics</code>, <code>contract-encoded-union-references</code>, <code>contract-validator-draft07</code>, <code>contract-evolution</code>, <code>contract-binary-fidelity</code> and <code>contract-binary-evolution</code>, plus <code>contract-versioned-retention</code> and <code>contract-versioned-binary-retention</code>. The data rows live in <code>test/fixtures/contract-fidelity</code>; binary pairs carry their expected values in their suite. Expected negatives are ordinary assertions, not skipped tests. Generated numeric witnesses are bounded and use seed <code>3107</code>.</p><p>Use Node 24 and the workspace pnpm version (the locked TypeSpec compiler requires Node 22 or newer), build first, then run the selected contract suites. The validators are test utilities, not emitter runtime dependencies.</p><p>These finite witnesses are counterexamples or evidence for a named consumer profile, <strong>not</strong> a proof of schema-language inclusion, compatibility with every client, or safety across every historic producer. Independent old/new compilations and the real version-generated retention matrix establish different evidence; neither establishes compatibility for every queued message or retention window.</p><p>AsyncAPI uses native draft-07, nullable unions and its own discriminator shape; it is not OpenAPI 3.0 <code>nullable</code> or HTTP request/response visibility projection. Partial lifecycle visibility does not select send/receive shapes. JSON encoded names are media-type-specific and are not binary field aliases. Application headers are not broker-native metadata. No fixture proves delivery, ordering, TTL, settlement, retries, exactly-once processing, deduplication, idempotency or business meaning.</p>',31)])])}const m=t(o,[["render",d]]);export{h as __pageData,m as default};
